  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { AgentSummary } from "./agent-summary";
 23→import { Message } from "./message";
 24→import { ControlRequest } from "./control-request";
 25→import { UserQuestion } from "./user-question";
 26→import { CondensedToolGroup } from "./condensed-tool-group";
 27→import { Button } from "@/components/ui/button";
 28→import { Terminal, MessageSquare, ListTodo } from "lucide-react";
 29→
 30→export function Chat({
 31→  connected,
 32→  loading,
 33→  status,
 34→  messages,
 35→  rawMessages,
 36→  onSendMessage,
 37→  onSpawnAgent,
 38→  onRespondToControl,
 39→  onRespondToUserQuestion,
 40→  showTasks,
 41→  onToggleTasks,
 42→  onToggleSidebar,
 43→}: {
 44→  connected: boolean;
 45→  loading?: boolean;
 46→  status: AgentStatus;
 47→  messages: ChatMessage[];
 48→  rawMessages: ClaudeMessage[];
 49→  onSendMessage: (content: string) => void;
 50→  onSpawnAgent: (prompt: string) => void;
 51→  onRespondToControl: (requestId: string, allow: boolean) => void;
 52→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 53→  showTasks?: boolean;
 54→  onToggleTasks?: () => void;
 55→  onToggleSidebar?: () => void;
 56→}) {
 57→  const [input, setInput] = useState("");
 58→  const [showRaw, setShowRaw] = useState(false);
 59→  const scrollRef = useRef<HTMLDivElement>(null);
 60→
 61→  useEffect(() => {
 62→    scrollRef.current?.scrollTo({
 63→      top: scrollRef.current.scrollHeight,
 64→      behavior: "smooth",
 65→    });
 66→  }, [messages, rawMessages, showRaw]);
 67→
 68→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 69→  const isActive = status === "connected" || status === "thinking";
 70→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 71→
 72→  function handleSubmit(e: React.FormEvent) {
 73→    e.preventDefault();
 74→    const trimmed = input.trim();
 75→    if (!trimmed) return;
 76→
 77→    if (isActive) {
 78→      onSendMessage(trimmed);
 79→    } else {
 80→      onSpawnAgent(trimmed);
 81→    }
 82→    setInput("");
 83→  }
 84→
 85→  return (
 86→    <div className="flex h-full flex-col">
 87→      <StatusBar
 88→        connected={connected}
 89→        status={status}
 90→        showRaw={showRaw}
 91→        onToggleRaw={() => setShowRaw((v) => !v)}
 92→        showTasks={showTasks}
 93→        onToggleTasks={onToggleTasks}
 94→        onToggleSidebar={onToggleSidebar}
 95→      />
 96→      <AgentSummary rawMessages={rawMessages} />
 97→
 98→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
 99→        {loading ? (
100→          <div className="flex h-full flex-col items-center justify-center gap-3">
101→            <div className="flex gap-1">
102→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
103→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
104→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
