"use client";

import { useState } from "react";
import { ChevronRight } from "lucide-react";
import type { CondensedGroup } from "@/lib/condense-messages";
import type { ToolCallInfo } from "@/lib/types";
import { Message } from "./message";
import { cn } from "@/lib/utils";

/** Format a tool name for display (strip common prefixes, shorten). */
function shortToolName(name: string): string {
  return name.replace(/^(mcp_\w+__|server\w+__)/, "");
}

/** Icon-like colored dot per tool category. */
const TOOL_COLORS: Record<string, string> = {
  Read: "bg-blue-400",
  Write: "bg-green-400",
  Edit: "bg-yellow-400",
  Bash: "bg-orange-400",
  Grep: "bg-purple-400",
  Glob: "bg-pink-400",
  WebFetch: "bg-cyan-400",
  Task: "bg-indigo-400",
};

function toolColor(name: string): string {
  return TOOL_COLORS[name] ?? "bg-muted-foreground";
}

export function CondensedToolGroup({ group }: { group: CondensedGroup }) {
  const [expanded, setExpanded] = useState(false);

  // Collect all tool calls with their result previews
  const allToolCalls: ToolCallInfo[] = group.messages.flatMap(
    (m) => m.toolCalls ?? []
  );

  return (
    <div className="py-1">
      <button
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
        className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-muted/50 transition-colors"
      >
        <ChevronRight
          className={cn(
            "size-3 shrink-0 transition-transform",
            expanded && "rotate-90"
          )}
        />
        <span className="font-mono">{group.summary}</span>
      </button>

      {/* Inline result previews (shown when collapsed) */}
      {!expanded && allToolCalls.some((tc) => tc.resultPreview) && (
        <div className="ml-7 mt-0.5 space-y-px">
          {allToolCalls.map((tc, i) => (
            <div
              key={tc.toolUseId ?? i}
              className="flex items-start gap-1.5 text-[11px] leading-snug"
            >
              <span
                className={cn(
                  "mt-[5px] size-1.5 shrink-0 rounded-full",
                  toolColor(shortToolName(tc.name))
                )}
              />
              <span className="text-muted-foreground/70 shrink-0">
                {shortToolName(tc.name)}
              </span>
              {tc.resultPreview && (
                <span className="truncate text-muted-foreground/50 font-mono">
                  {tc.resultPreview}
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      {expanded && (
        <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
          {group.messages.map((msg) => (
            <Message key={msg.id} message={msg} />
          ))}
        </div>
      )}
    </div>
  );
}

